func (i brainIgnore) MentionsIgnoredPath(text string) bool {
	text = filepath.ToSlash(text)
	if text == "" {
		return false
	}
	for _, pattern := range append([]string{".env", ".pem", ".key", "secret/"}, i.patterns...) {
