		}
	}
	return nil
}

func probeWritableDir(dir string) error {
	if err := ensureDir(dir); err != nil {
		return fmt.Errorf("create directory: %w", err)
	}
	f, err := os.CreateTemp(dir, ".write-test-*")
	if err != nil {
